jiti.source:
import { pathToFileURL } from 'node:url';
export function createJiti(base) { return { import: async (specifier, options) => { const url = specifier.startsWith('file:') ? specifier : pathToFileURL(specifier).href; const mod = await import(url); return options && options.default ? (mod.default ?? mod) : mod; } }; }
export default createJiti;

